SELECT wallet_id, player_id, currency_code, wallet_type, balance, locked_amount, (balance - locked_amount) AS available_balance, create_time, update_time FROM t_wallet
deleted = FALSE
AND player_id = #{query.playerId}
AND wallet_type = #{query.walletType}
AND currency_code = #{query.currencyCode}
ORDER BY wallet_id ASC
